                                        <button type="submit" class="toggle-btn">
                                            {% if task.completed %}Mark Incomplete{% else %}Mark Complete{% endif %}
                                        </button>
                                    </form>
                                </li>
                            {% endfor %}
                        </ul>
                    {% else %}
                        <p style="font-size: 14px; color: #666;">No tasks in this list yet.</p>
                    {% endif %}

                    <form class="task-form" action="{{ url_for('add_task', list_id=lst.id) }}" method="POST">
                        <input type="text" name="description" placeholder="Add a new task..." required>
                        <button type="submit">Add Task</button>
                    </form>
                </div>
            {% endfor %}
        {% else %}
            <p>No to-do lists yet. Create one above!</p>
        {% endif %}
    </div>
</body>
</html>
